B="BK-741"
C=[
("S12",3251,3259,"لماذا يُطلب تقدير العمر: لأن القانون يربط الحقوق بالسن","يربط القانون بين العمر وحدود المسؤولية وسن الزواج وغيرها، فيُطلب من الطبيب تقدير العمر عند غياب الأوراق. يحتاج هذا التقدير إلى نطاق لا إلى رقم دقيق.","اطلب نطاقاً عمرياً مع بيان الطريقة، وقارنه بالوثائق الرسمية إن وجدت.","التقدير الجسدي للعمر يحمل هامش خطأ كبيراً، وتختلف الأجسام بحسب التغذية والصحة.","","16-18","safe","reporting",["KO-FC-04-021","KO-RS-07B-001"],["تقدير العمر","نطاق"]),
("S12",3255,3259,"العظام تحفظ تاريخ الإصابة ولكنها لا تعطي توقيتاً بالأيام","عند العثور على هيكل عظمي يمكن أن تدل علامات الالتئام على أن إصابة قديمة وقعت في حياة الشخص، وأن الكسر غير الملتئم قد يشير إلى وقوعه قرب الوفاة. تُقدَّر مدة بقاء الجسد بنطاق واسع جداً.","اسأل: هل الإصابة حدثت قبل الوفاة بزمن، أم قربها؟ ولا تَعِد بتاريخ دقيق.","التقدير الزمني للهياكل غير دقيق وتتحكم فيه البيئة.","العظام تحدد يوم الوفاة.","18+","conceptual","timing",["KO-FC-04-021","KO-FC-04-022"],["التئام","نطاق زمني"]),
("S12",3260,3305,"قضية: خطة بحث مرتبة قبل تحديد من الفاعل","تعرض القضية الأولى خطتين متتاليتين: الأولى لمعرفة هوية المجني عليه (نشر الصورة والأوصاف وفحص البلاغات)، والثانية لمعرفة من استفاد ومن كان معه (علاقاته، حركته، الشهود، رواية الأقرباء). النتائج جاءت لأن الأسئلة رُتبت بدل القفز إلى مشتبه به.","في اللعبة: قسّم الملف إلى مرحلتين، من هو؟ ثم ماذا جرى له؟","النجاح في قضية لا يثبت أن الخطة تصلح لكل قضية.","","16-18","conceptual","reporting",["KO-RS-05-002","KO-RS-05-005","KO-RS-06-017"],["خطة بحث","تسلسل الأسئلة"]),
("S12",3293,3300,"تناقض رواية قريب مع تسلسل الأحداث يستدعي التحقق لا الاتهام","في القضية الأولى ظهر أن رواية قريبة المجني عليه عن خروجه تتعارض مع معلومات من مصادر أخرى، فركّز المحققون عليها. جاء الاتهام بعد التأكد من عدة مصادر، وليس بمجرد التناقض.","التناقض سبب للمراجعة: اسأل ما الذي يفسره غير الكذب؟ ثم ابحث عن مصادر مستقلة.","التناقض قد ينشأ من النسيان أو الخوف أو سوء الفهم.","كل من تتناقض روايته مذنب.","16-18","conceptual","witness_reliability",["KO-RS-05-014","KO-RS-05-007","KO-RS-05-009"],["تناقض","تحقق مستقل"]),
("S12",3306,3331,"قضية: متعلقات المجني عليه تدل على أصله ومهنته","في القضية الثانية استُدل من الملابس والحال الظاهر على أن الضحية قد يكون عاملاً مهاجراً، فوُجِّه البحث إلى أماكن العمل التي يرتادها أمثاله، ومنها وصل المحققون إلى اسمه. اعتمد الأمر على فرضية قابلة للاختبار.","صغ فرضية عن الخلفية الاجتماعية من الأدلة المادية ثم اختبرها بسؤال مباشر في الأماكن المحتملة.","الاستدلال من المظهر على المهنة أو الأصل قد يخطئ ويجب ألا يُعامل كحقيقة.","","16-18","conceptual","witness_reliability",["KO-RS-06-007","KO-RS-06-010"],["فرضية قابلة للاختبار","استدلال من المظهر"]),
("S12",3333,3385,"قضية جثة في مجرى مائي: حساب المسار الزمني بمعلومات مهندسي الري","في القضية الثالثة قدّر المحققون مدة وجود الجثة في الماء من الفحص، ثم عادوا بمعلومات عن اتجاه التيار وسرعته إلى المناطق التي يمكن أن تكون قد دخلت منها. دُعمت النتيجة بشهود رأوا الجثة في أماكن سابقة.","في الألغاز: حوّل مدة الانجراف إلى مسافة مع هامش، ثم طابق مع شهادات مشاهدين على الطريق.","سرعة التيار تتغير، وتقدير مدة الغمر ينطوي على هامش كبير.","","16-18","conceptual","timing",["KO-FC-04-021","KO-RS-05-005","KO-RS-05-004"],["مدة الغمر","مسار التيار"]),
("S12",3350,3385,"مفاتيح الكشف: التتبع المالي والتغيّر المفاجئ في سلوك الإنفاق","تنتهي القضية الثالثة بالوصول إلى شخص ظهرت عليه مظاهر ثراء مفاجئ بعد الاختفاء، ثم تأكدت الصلة بوثائق مزورة وأموال تحركت. التحول المفاجئ في الإنفاق قرينة تبعث على التحقق لا على الحكم.","أضف إلى جدول الأدلة: مَن تغيّر وضعه المادي بعد الواقعة؟ ثم تحقق من مصدر المال بالوثائق.","الثراء المفاجئ له أسباب كثيرة بريئة، وهو مؤشر لا دليل.","","16-18","conceptual","reporting",["KO-RS-06-010","KO-RS-05-004"],["قرينة","مصدر المال"]),
("S12",3386,3412,"قضية: التعرف عبر مقارنة أثر بإضبارة شخصية قديمة","في القضية الرابعة جرى التأكد من هوية الضحية بمقارنة آثار الأصابع المأخوذة منه بسجل قديم محفوظ في ملف خدمته، بعد أن ذكر الأهل تشابه الملابس. تعرّف الأقارب وحده لم يكن كافياً فسعى المحققون إلى تأكيد مادي مستقل.","اطلب تأكيداً مستقلاً بوسيلة مختلفة عن التعرف البصري من الأقارب.","التعرف البصري عرضة للتوقع النفسي، وسجل المقارنة قد يكون ناقصاً أو قديماً.","","16-18","safe","witness_reliability",["KO-RS-05-004","KO-RS-05-008","KO-FC-04-012"],["تأكيد مستقل","تعرف الأقارب"]),
("S12",3386,3412,"الحبكة التي تبدأ بعلاقة مالية: من يملك دافعاً ومن يملك فرصة؟","كشف التحقيق في القضية الرابعة عن دَين صغير ومطالبة بمبلغ آخر بين المجني عليه وقريبه، مما حدّد من كان على علم بتنقلاته. الدافع المحتمل وحده لا يكفي دون أدلة تربط بالفرصة.","اجمع لكل مشتبه ثلاثة أشياء: دافع محتمل، فرصة ممكنة، دليل مادي أو شهادة مستقلة.","الدافع المحتمل يتوفر عند أناس كثيرين.","","all","safe","witness_reliability",["KO-RS-06-006","KO-RS-06-010"],["دافع","فرصة"]),
("S13",3414,3432,"أعمال الطبيب الشرعي أوسع من التشريح","تشمل مهامه فحص الوفيات المشتبه بها، وإبداء الرأي في تقارير أخرى، ومعاينة المسرح مع النيابة، وفحص الجرحى، وتقدير العمر، والاستعراف. من يعرف حدود تخصصه يعرف متى يستعين بغيره.","اعرف لكل سؤال في القضية من يُسأل: الطبيب الشرعي أم الكيميائي أم خبير الخطوط.","التخصصات تتداخل لكن لكل منها حدود، والرأي خارج الحدود أضعف.","","13-15","safe","reporting",["KO-FC-04-022","KO-FC-04-031"],["اختصاص","خبير"]),
("S13",3436,3451,"الطبيب الشرعي لا يُعطي رأياً لأحد الخصوم، بل للجهة التي ندبته","تنص تعليمات المصلحة على أن التقارير تصدر استجابة لطلب جهات التحقيق أو القضاء لا لطلب شخص عادي، وأن تقارير الجنايات تُراجَع من رئيس القسم قبل إصدارها. الهدف حياد الخبرة وتوحيد الجودة.","اسأل: من طلب هذا التقرير؟ ومن راجعه؟ هذه أسئلة تقيس الحياد.","اختلاف الجهات والأنظمة يجعل هذه القواعد خاصة بالنظام المذكور.","","16-18","safe","reporting",["KO-FC-04-027","KO-FC-04-031"],["حياد الخبير","مراجعة داخلية"]),
("S13",3447,3449,"عند الخلاف داخل الفريق يُرفع الأمر إلى مرجع أعلى","تلزم التعليمات رئيس القسم بإبلاغ الطبيب بملاحظاته، وإن لم يقتنع رُفع الأمر إلى كبير الأطباء. هذا إجراء يقلل من الانفراد بالرأي.","في الألغاز: وجود مراجعة ثانية مستقلة يرفع الثقة بالنتيجة.","المراجعة الداخلية لا تغني عن رقابة خارجية عند الحاجة.","","16-18","safe","lab_limits",["KO-FC-04-027","KO-FC-04-031"],["مراجعة الأقران"]),
("S13",3465,3469,"الكشف الظاهري يكفي أحياناً ولا يكفي دائماً","تقيّد التعليمات الاكتفاء بالفحص الظاهري، فالأصل التشريح، ويُكتفى بالظاهر حين يؤكد التحقيق أن الواقعة عرضية وكان الفحص كافياً، وعلى الطبيب أن ينبّه إن رأى غير ذلك. الفكرة أن قرار تخفيف الفحص يجب ألا يُتخذ بطلب خارجي وحده.","اسأل: ما الذي يمكن أن نخسره إن اكتفينا بفحص أقل؟","تخفيف الفحص يزيد احتمال أن نغفل شيئاً.","الكشف الظاهري يكشف كل شيء.","16-18","conceptual","lab_limits",["KO-RS-05-013","KO-FC-04-022"],["كشف ظاهري","تشريح"]),
("S13",3472,3478,"المكان والسرعة: الفحص المبكر يحمي الدليل من التغير","تنبه التعليمات إلى إنجاز فحص الجثث بسرعة، خاصة في الحر، حتى لا تطمس التغيرات اللاحقة ما يُراد معرفته. التأخير يغير الدليل نفسه.","في الألغاز: كل ساعة تأخير قد تضيّق ما يمكن استنتاجه، فاسأل متى فُحص الجسد.","السرعة لا تعني التسرع في الاستنتاج.","","16-18","safe","timing",["KO-FC-04-021","KO-FC-04-026"],["تأخير الفحص","تغيّر الدليل"]),
("S13",3479,3480,"قياس درجة الحرارة يُسجَّل ويُذكر معه الظرف","يوصي النص بأخذ حرارة الجثة وتثبيتها في التقرير ما لم يكن التعفن متقدماً. القراءة بلا ظروف المكان والملابس والوقت لا تفيد.","سجّل القراءة مع وقتها وحرارة المحيط والظروف، ولا تستخلص ساعة وفاة واحدة منها.","تبريد الجسد يتأثر بالحرارة المحيطة والملابس والجسد نفسه فيعطي نطاقاً لا لحظة.","درجة حرارة الجسد تعطي ساعة الوفاة بدقة.","16-18","safe","timing",["KO-FC-04-021","KO-FC-04-020"],["حرارة الجسد","نطاق"]),
("S13",3481,3491,"السلامة المهنية جزء من جودة العمل","تفصّل التعليمات احتياطات الوقاية من العدوى للفاحص، ومنها القفازات وغسل اليدين والتعامل مع الجروح. حماية العامل تحمي كذلك العينات من التلوث.","اسأل: هل وُثّق لبس القفازات وتغييرها؟ هذه تفاصيل تؤثر على الثقة بالعينة.","هذه إرشادات قديمة وتُحدَّث اليوم بمعايير سلامة أحدث.","","13-15","safe","evidence_handling",["KO-FC-04-026","KO-FC-04-007"],["تلوث","قفازات"]),
("S13",3492,3504,"الفحص الكامل منظم ومكتوب بقياسات حقيقية","تدعو التعليمات إلى فحص كل التجاويف لا واحدة منها، وتسجيل أبعاد كل إصابة بالأرقام بدل 'نحو' و'تقريباً'، وتقليل الإتلاف غير الضروري. المنهج الكامل يمنع الاستنتاج من جزء.","تحقق من تقرير: هل قاس كل إصابة؟ هل فحص كل المواضع أم ركّز على واحد؟","القياس الدقيق لا يصحح خطأ في التفسير.","","16-18","conceptual","reporting",["KO-FC-04-031","KO-FC-04-026"],["قياس","فحص شامل"]),
("S13",3515,3516,"لا يُعلن رأي في سبب الوفاة على المسرح إذا كانت الصورة غامضة","تمنع التعليمات الطبيب من إبداء رأي شفوي أو كتابي في الموقع حين يرى غموضاً، وتطلب التريث والاحتفاظ بالعينات وعرضها على رئيس القسم. التعجل في إعلان السبب يضر بالتحقيق.","في الألغاز: عبارة 'سنعرف بعد الفحص' علامة تحفظ منهجي وليست تهرباً.","الحالات الواضحة تقبل رأياً أولياً مع حفظ نسخة مما قيل.","","13-15","safe","reporting",["KO-FC-04-022","KO-FC-04-031","KO-RS-07B-001"],["تريّث","رأي أولي"]),
("S13",3519,3527,"حفظ العينات يتبع غرض الفحص","تفرّق التعليمات بين ما يوضع في محلول حفظ للفحص النسيجي وما يوضع في وعاء معقم للفحص الجرثومي، وبأن العينات تُحفظ حين يكون هناك خلاف في الرأي. اختيار الحفظ الخاطئ يُتلف الدليل.","اسأل: ما الفحص المطلوب؟ فهو الذي يحدد كيف تُحفظ العينة.","التفاصيل الدقيقة تتغير مع المعايير الحديثة.","","16-18","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["حفظ عينة","غرض الفحص"]),
("S13",3528,3546,"إخراج الجثة لإعادة الفحص: يلزم أولاً تأكيد القبر والسياق","تنظم التعليمات إخراج الجثث بأمر جهة التحقيق بعد رأي الطبيب، وتطلب الاستعراف على القبر أولاً، ومعرفة ظروف الواقعة قبل الفحص. بعض الدلائل كالكسور تبقى بعد زمن طويل.","في الألغاز: قبل فتح ملف قديم تأكد أن الجثة هي المقصودة، ومن حضر عملية الإخراج.","فحص جثة بعد زمن يحد من نوع الاستنتاجات الممكنة.","","18+","conceptual","evidence_handling",["KO-FC-04B-002","KO-FC-04-026","KO-FC-04-021"],["إخراج","سلسلة حيازة"]),
("S13",3547,3569,"من يُسأل عن ماذا: توزيع مهام الخبراء حسب قسم العمل","تحدد التعليمات أن أطباء الطب الشرعي يفحصون الإصابات والوفيات، وقسم الأبحاث المصلية والميكروسكوبية يفحص الدم والشعر والأقمشة، والكيميائيون يحللون السموم والمواد، وقسم التزييف يفحص الأوراق والخطوط. يسأل المحقق كل خبير عن نطاق تخصصه.","اربط كل سؤال بالخبير المناسب في ملف القضية، واكتب سؤالاً محدداً لا عاماً.","الإحالة إلى الخبير الخطأ قد تضيع الوقت أو تعطي نتيجة خارج التخصص.","","13-15","safe","lab_limits",["KO-FC-04-031","KO-FC-04-019"],["اختصاص الخبراء","سؤال محدد"]),
("S13",3569,3573,"سؤال تكميلي بعد التقرير: الأسئلة المكتوبة تُرسل للخبير نفسه","تسمح التعليمات بإرسال مذكرة تكميلية للطبيب حين تستجد نقطة، وباستدعائه للمناقشة عند الضرورة. إعادة الاستيضاح جزء من العمل وليست تشكيكاً.","اكتب الأسئلة بوضوح وتجنب أسئلة توحي بالجواب المطلوب.","صياغة السؤال قد توجه الجواب فيجب أن تبقى محايدة.","","16-18","conceptual","reporting",["KO-FC-04-027","KO-FC-04-031"],["سؤال تكميلي","حياد الصياغة"]),
("S13",3577,3589,"إرسال المواد إلى المعمل يتم مع أوراق تصف الظروف دون فرض الاستنتاج","تقول التعليمات إن الإرسال يكون بالأوراق الكاملة وبغلاف مختوم وإيصال، وبإيضاح ما يلزم من ظروف الواقعة. المبدأ: المعلومات الضرورية فقط، لأن الإفراط قد يوجّه الخبير.","أرسل ما يلزم الفحص، واحتفظ بنظريتك الخاصة بعيداً عن الخبير.","إخبار الخبير بما يتوقعه المحقق يزيد خطر التحيز السياقي.","","16-18","conceptual","lab_limits",["KO-FC-04-027","KO-FC-04B-002"],["تحيز سياقي","معلومات لازمة"]),
("S13",3591,3607,"التشريح ليس إجراءً روتينياً: يُقرَّر بحسب الشبهة","توضح التعليمات حالات لا يلزم فيها التشريح (وفاة بمستشفى بلا شبهة، سقوط عرضي) وحالات يلزم (جريمة، جثة طافية، حرق، وجود شبهة). المعيار هو وجود شبهة جنائية أو سؤال لا يُحسم بدونه.","اسأل: ما السؤال الذي لا يجيب عنه إلا هذا الفحص؟","هذه قواعد نظام قانوني محدد وقد تختلف في غيره.","","16-18","conceptual","reporting",["KO-FC-04-022","KO-RS-06-001"],["شبهة جنائية","ضرورة الفحص"]),
("S13",3612,3615,"المعاينة ليلاً تضعف، فيُحفظ المكان إلى الصباح","تمنع التعليمات تكليف الطبيب بمعاينة مكان الحادث ليلاً، وتطلب حفظ الحالة كما هي حتى ضوء النهار لما فيه من جودة رؤية وتوثيق. الإضاءة الضعيفة تُخفي الآثار الصغيرة.","في الألغاز: اسأل عن ظروف الإضاءة وقت المعاينة، فقد تفسر ما فات.","هناك حالات عاجلة لا تحتمل التأجيل.","","13-15","safe","scene_documentation",["KO-FC-04-026","KO-RS-05-013"],["إضاءة","حفظ المكان"]),
("S13",3618,3631,"التقرير الطبي عن إصابة: وصف وسبب وتاريخ وأداة ومدة علاج","تطلب التعليمات أن يبين التقرير وصف الإصابة وسببها وتاريخها والأداة والمدة اللازمة للعلاج. غياب أحد هذه العناصر يضعف فائدة التقرير.","قارن أي تقرير بهذه القائمة: ما الذي غاب؟ ثم اطلب استيفاءه.","التاريخ والأداة المقدّران من الفحص يظلان تقديرات.","","16-18","safe","reporting",["KO-FC-04-031","KO-FC-04-022"],["تقرير","قائمة تحقق"]),
("S13",3634,3645,"التحريز: كل مصدر في حرز مستقل والختم يُسجَّل","توجب التعليمات تحريز ما يخص كل مشتبه أو مجني عليه على حدة، وإرسال المضبوطات بيد شرطي مع إيصال واستمارة تصف الأحراز والأختام وظروف الضبط. يُوضع نموذج الختم على المحضر ليُقارن لاحقاً.","اسأل عن كل دليل: من ضبطه؟ في أي حرز؟ ما رقم الختم؟ من استلمه؟","السلسلة الجيدة تثبت عدم العبث لكنها لا تثبت صحة الاستنتاج.","السلسلة المكتملة تعني أن الدليل صحيح.","all","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["حرز","ختم","سلسلة حيازة"]),
("S13",3646,3669,"العناصر الملوثة لا تُخلط في حرز واحد","تمنع التعليمات وضع مضبوطات ملوثة بالدم بعضها فوق بعض، وتأمر بتجفيف الملابس قبل تغليفها، وبأخذ الجزء الحامل للأثر كاملاً إن أمكن بدل الحك، ومع التصوير قبل الرفع. الغرض منع انتقال الأثر أو فساده.","في الألغاز: إن وُضعت قطعتان معاً في كيس واحد فاسأل هل يمكن الوثوق بنتيجة نقل الأثر.","التلوث التبادلي قد يخلق أثراً لم يكن موجوداً.","","all","safe","evidence_handling",["KO-FC-04-007","KO-FC-04-026"],["تلوث تبادلي","تجفيف","تحريز"]),
("S13",3657,3660,"عينات الأظافر تُجمع بحرص وتُفصل لكل يد","تنص المادة على أخذ قلامات الأظافر في مكان محمي من تيارات الهواء وتجنب الجروح حتى لا تختلط بدم الفاحص أو جلده، وبوضع كل يد في حرز. التحليل بعد ذلك يعطي ما وُجد لا كيف وصل.","اسأل: هل فُصلت اليدان؟ هل جُمعت العينة قبل غسل اليدين؟","وجود مادة تحت الأظافر لا يحدد كيف وصلت إليها.","","18+","conceptual","evidence_handling",["KO-FC-04-007","KO-FC-04-020"],["عينة أظافر","انتقال"]),
("S13",3666,3667,"الحك لا يكفي لجمع بقعة من جدار","يذكر النص أن كشط البقع من طبقات الدهان قد يفقد جزءاً مهماً من المادة التي تنفذ إلى الداخل، فيُفضل رفع الطبقة كاملة أو الجزء الحامل. جمع الدليل بطريقة ناقصة يغير ما يمكن أن يقوله.","اسأل لماذا جُمعت العينة بهذه الطريقة، وهل كان هناك بديل أفضل.","هذه إرشادات قديمة وتحتاج مراجعة بمعايير الجمع الحديثة.","","16-18","safe","evidence_handling",["KO-FC-04-026","KO-FC-04-019"],["جمع عينة","فقد مادة"]),
("S13",3671,3688,"ملف التسمم المشتبه: الحفاظ على ما يخرج من المصاب وعلى الأوعية","توصي المواد بحفظ ما يتوفر من إفرازات المصاب وأوعية الطعام والشراب، وتدوين زمن الأعراض بدقة وما أُعطي من إسعاف، وسؤال الآخرين عمن تناول المادة نفسها. هذه المعلومات تقيّم لاحقاً قيمة النتيجة المخبرية.","في الألغاز: اسأل متى بدأت الأعراض؟ ومن تناول الشيء نفسه؟ وماذا أُعطي من علاج قبل أخذ العينة؟","وجود مادة في عينة لا يثبت أنها سبب الأعراض أو أنها دُسّت.","وجود السم في العينة يثبت القصد.","16-18","conceptual","timing",["KO-FC-04-020","KO-FC-04-019","KO-RS-05-005"],["عينة بيولوجية","تسلسل الأعراض"]),
("S13",3689,3700,"المواد المشتعلة والمخدرة تحتاج تغليفاً مستقلاً وتوثيقاً للكمية","تأمر المواد بوضع القابل للاشتعال في حرز منفصل مع بيان ذلك على الغلاف، وبتحريز ما يخص كل مشتبه على حدة، وأخذ عينات بمقادير محددة للتحليل وحفظ الباقي. يُسجل كل ذلك في المحضر.","اقرأ المحضر بحثاً عن: هل وُزنت المادة؟ هل أُخذت عينة؟ هل حُفظ الباقي؟","فحص جزء من المضبوط لا يثبت بالضرورة أن الباقي مماثل إذا كان غير متجانس.","","16-18","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["عينة تمثيلية","وزن"]),
]
